css:
.brutalist-container {
  position: relative;
  width: 300px;
  height: 110px; /* Original compact height */
  cursor: pointer;
  transition: height 0.6s cubic-bezier(0.19, 1, 0.22, 1);
}

.brutalist-container:hover {
  height: 300px; /* Expanded height on hover */
}

.concrete-block {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: #000;
  border: 8px solid #000;
  transition: all 0.6s cubic-bezier(0.19, 1, 0.22, 1);
  overflow: hidden;
}

.brutalist-container:hover .concrete-block {
  transform: translate(0px, 0px) rotate(0deg);
  box-shadow:
    12px 12px 0 #333,
    24px 24px 0 #666,
    36px 36px 0 #999;
}

.concrete-texture {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: repeating-linear-gradient(
      45deg,
      #000 0px,
      #000 2px,
      #111 2px,
      #111 4px
    ),
    repeating-linear-gradient(
      -45deg,
      transparent 0px,
      transparent 8px,
      rgba(255, 255, 255, 0.05) 8px,
      rgba(255, 255, 255, 0.05) 10px
    );
  opacity: 0.3;
}

.main-content {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
}

.title-text {
  color: #fff;
  font-size: 32px;
  font-weight: 400;
  letter-spacing: 6px;
  text-transform: uppercase;
  transition: all 0.5s cubic-bezier(0.68, -0.55, 0.265, 1.55);
  text-shadow:
    2px 2px 0 #333,
    4px 4px 0 #666;
}

.brutalist-container:hover .title-text {
  opacity: 0;
  transform: translateY(-40px) rotateX(90deg) scale(0.3);
  filter: blur(8px);
}

.todo-grid {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: grid;
  grid-template-rows: repeat(6, 1fr);
  gap: 10px;
  padding: 14px;
  padding-top: 20px;
  opacity: 0;
  transform: translateY(-1px) rotateX(-100deg) scale(1.3);
  transition: all 0.6s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.brutalist-container:hover .todo-grid {
  opacity: 1;
  transform: translateY(0) rotateX(0deg) scale(1);
}

.todo-item {
  position: relative;
  display: flex;
  align-items: center;
  padding-left: 5px;
}

.todo-checkbox {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.todo-label {
  position: relative;
  color: #fbf9f9;
  font-family: "Arial", monospace;
  font-size: 15px;
  letter-spacing: 1px;
  cursor: crosshair;
  padding-left: 25px;
  transition: all 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.todo-label:before {
  content: "";
  position: absolute;
  left: -15px;
  top: 0;
  width: 20px;
  height: 20px;
  border: 4px solid #d0cbcb;
  background: transparent;
  transition: all 0.3s ease;
}

.todo-checkbox:checked + .todo-label:before {
  background: #be0202;
  border-color: #f9f4f4;
}

.todo-checkbox:checked + .todo-label:after {
  content: "";
  position: absolute;
  left: -7px;
  top: -4px;
  width: 8px;
  height: 25px;
  border: solid #faf7f7;
  border-width: 0 3px 2px 0;
  transform: rotate(45deg);
}

.todo-checkbox:checked + .todo-label {
  text-decoration: line-through;
  color: #f60101;
  transform: translateX(-4px);
}

/* Concrete slab backgrounds */
.slab-bg {
  position: absolute;
  background: #04040404;
  border: 4px solid #f4efef;
  z-index: -1;
  transition: all 0.6s cubic-bezier(0.19, 1, 0.22, 1);
}

.slab-1 {
  top: 18px;
  left: 18px;
  width: 264px;
  height: 74px;
}

.slab-2 {
  top: 36px;
  left: 36px;
  width: 228px;
  height: 38px;
}

.brutalist-container:hover .slab-1 {
  height: 144px;
  transform: translate(20px, 20px) rotate(1deg);
}

.brutalist-container:hover .slab-2 {
  height: 108px;
  transform: translate(-10px, 30px) rotate(-1deg);
}

/* Industrial corner brackets */
.corner-bracket {
  position: absolute;
  width: 20px;
  height: 20px;
  border: 4px solid #000;
  background: #fff;
  transition: all 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.bracket-tl {
  top: -10px;
  left: -10px;
  border-right: none;
  border-bottom: none;
}

.bracket-tr {
  top: -10px;
  right: -10px;
  border-left: none;
  border-bottom: none;
}

.bracket-bl {
  bottom: -10px;
  left: -10px;
  border-right: none;
  border-top: none;
}

.bracket-br {
  bottom: -10px;
  right: -10px;
  border-left: none;
  border-top: none;
}

.brutalist-container:hover .corner-bracket {
  transform: scale(1.5);
  background: #000;
  border-color: #fff;
}

/* Typography accent */
.type-accent {
  position: absolute;
  top: -30px;
  left: 0;
  font-family: "JetBrains Mono", monospace;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
  color: #000;
  transition: all 0.4s ease;
  opacity: 0;
}

.brutalist-container:hover .type-accent {
  opacity: 1;
  transform: translateY(5px);
}

/* Industrial rivets */
.rivet {
  position: absolute;
  width: 8px;
  height: 8px;
  background: #000;
  border-radius: 50%;
  border: 2px solid #333;
  transition: all 0.3s ease;
}

.rivet:nth-child(1) {
  top: 10px;
  left: 10px;
}
.rivet:nth-child(2) {
  top: 10px;
  right: 10px;
}
.rivet:nth-child(3) {
  bottom: 10px;
  left: 10px;
}
.rivet:nth-child(4) {
  bottom: 10px;
  right: 10px;
}

.brutalist-container:hover .rivet {
  background: #fff;
  transform: scale(1.5);
}

/* Scan line effect */
.scan-effect {
  position: absolute;
  top: 0;
  left: -100%;
  width: 4px;
  height: 100%;
  background: linear-gradient(180deg, transparent, #fff, transparent);
  transition: all 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  opacity: 0.8;
}

.brutalist-container:hover .scan-effect {
  left: 100%;
}

/* Paper texture overlay */
.paper-texture {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(
      circle at 20% 50%,
      transparent 20%,
      rgba(255, 255, 255, 0.3) 21%,
      rgba(255, 255, 255, 0.3) 34%,
      transparent 35%,
      transparent
    ),
    linear-gradient(
      0deg,
      transparent 24%,
      rgba(255, 255, 255, 0.05) 25%,
      rgba(255, 255, 255, 0.05) 26%,
      transparent 27%,
      transparent 74%,
      rgba(255, 255, 255, 0.05) 75%,
      rgba(255, 255, 255, 0.05) 76%,
      transparent 77%,
      transparent
    );
  pointer-events: none;
}
